from typing import List
import heapq

class Solution:
    def kClosest(self, points: List[List[int]], k: int) -> List[List[int]]:
        heap = []
        for x, y in points:
            dist = x * x + y * y
            heapq.heappush(heap, (-dist, x, y))
            # The farthest among kept points is removed.
            if len(heap) > k:
                heapq.heappop(heap)
        return [[x, y] for _, x, y in heap]

